      }
    }

    if (game.mode === 'title') drawTitle(game);
    if (game.mode === 'paused') drawPause(game);
    if (game.mode === 'landed' || game.mode === 'crashed') drawEnd(game);
  }

  resize();
  window.addEventListener('resize', resize);
  return { state, resize, draw, setMessage };
}
