import { COLORS, HUD_COPY, WORLD } from './config.js';
import { clamp, createRng } from './noise.js';

const THREE = globalThis.THREE;

const MISSION_STARTS = {
  ring: {
    x: 0,
    y: 240,
    z: -1700,
    yaw: 0,
    pitch: 0,
    roll: 0,
    speed: 58,
    throttle: 0.78,
  },
  landing: {
    x: 0,
    y: 168,
    z: -760,
    yaw: 0,
    pitch: -2.5,
    roll: 0,
    speed: 48,
    throttle: 0.27,
  },
  free: {
