export function createMissions(scene) {
  const group = new THREE.Group();
  group.name = 'mission-objects';
  scene.add(group);

  const mission = {
    id: null,
    nextRingIndex: 0,
    rings: [],
    startedAt: 0,
    startPosition: new THREE.Vector3(),
    landing: {},
